  "prediction_basis_card_ids": ["C72", "C76", "C78", "C79"],
  "claims": [
    {
      "claim": "L6 hepatic-clearance records for BTK inhibitors sharing the query's acryloylpiperidine and 4-phenoxyphenyl motif show substantial CYP3A-mediated hepatic metabolism: zanubrutinib has a human liver microsomal CYP3A intrinsic clearance of 120 µL/(min·mg) and is primarily cleared by hepatic CYP3A, while acalabrutinib has an additional human liver microsomal intrinsic clearance of 289.5 µL/(min·mg). This is coherent measured evidence of high first-pass hepatic extraction in this chemical class.",
      "card_ids": ["C72", "C76", "C78", "C79"]
    },
    {
      "claim": "The earlier absorption evidence (high permeability, rapid Tmax, no appreciable efflux in close analogs) supports intestinal absorption but does not address hepatic first-pass loss; high permeability alone is insufficient to establish F ≥ 20% when the class shows high hepatic intrinsic clearance.",
      "card_ids": ["C59", "C65", "C46", "C49", "C50", "C53", "C55", "C56", "C35", "C38", "C40", "C42"]
    },
    {
      "claim": "The L1/L2 low-F outcomes come from structurally unrelated scaffolds and are not used as direct votes; the low prediction is based on the L6 mechanistic clearance evidence rather than those contexts.",
      "card_ids": ["C01", "C03", "C04", "C12", "C14", "C15", "C16"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "changed",
      "card_ids": ["C72", "C76", "C78", "C79"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement is supplied for the query itself.",
    "No direct human liver microsomal intrinsic clearance value is supplied for the query; L6 values are for zanubrutinib, acalabrutinib, and other analogs.",
    "Fed-state effects on the query are not directly measured; the L6 hepatic-clearance data are not fed-specific.",
    "No human F value for zanubrutinib or acalabrutinib is supplied to calibrate the CLint values to the F ≥ 20% threshold.",
    "Query-specific solubility and formulation are not directly measured."
  ],
  "decision_summary": "Flip to low: L6 adds mechanistic hepatic-clearance evidence showing that BTK inhibitors with the query's acryloylpiperidine/4-phenoxyphenyl motif are primarily cleared by hepatic CYP3A with high human liver microsomal intrinsic clearance, supporting substantial presystemic loss. The absorption evidence remains favorable but does not overcome this first-pass liability, and no affirmative evidence supports F ≥ 20% for the query."
}

